 return heading('Biblioteca de imagens','Imagens públicas do site. Não envie documentos ou informações privadas.',`<button class="primary" data-upload-media>Adicionar imagem</button>`)+`<div class="dashboard-grid">${images.map(r=>`<article class="panel"><div class="panel-body">${r.published?`<img src="/api/app?action=media&id=${r.id}" alt="${e(r.alt)}" style="width:100%;height:180px;object-fit:cover;border-radius:6px">`:''}<h3>${e(r.filename)}</h3><p class="muted">${e(r.alt)} · ${Math.ceil(r.size/1024)} KB</p><div class="actions" style="margin-top:12px"><button class="small" data-media-toggle="${r.id}">${r.published?'Despublicar':'Publicar imagem'}</button>${r.published?`<button class="small" data-media-copy="${r.id}">Copiar URL</button>`:''}</div></div></article>`).join('')||empty('Nenhuma imagem enviada','Envie uma fotografia e publique para utilizar seu endereço no conteúdo do site.')}</div>`;
