async function agenda(){
 const data=eventId?events.filter(r=>r.id===eventId):events;
 const tasks=eventId?await all('tasks',eventId):manager()?await all('tasks'):[];
 const items=[...data.filter(r=>r.data.date&&r.data.status!=='Cancelado').map(r=>({date:r.data.date,title:r.data.title,type:'Evento',event:r.id,status:r.data.status})),...tasks.filter(r=>r.data.due&&r.data.status!=='Concluída').map(r=>({date:r.data.due,title:r.data.title,type:'Tarefa',event:r.event_id,status:r.data.status}))].sort((a,b)=>a.date.localeCompare(b.date));
 return heading('Agenda de eventos e tarefas','Datas do planejamento reunidas para organizar os próximos passos.')+`<div class="panel">${items.map(r=>`<a class="row-item" href="#event:${e(r.event)}"><div class="date-tile">${e(r.date.slice(8))}<small>${e(r.date.slice(5,7))}</small></div><div class="grow"><strong>${e(r.title)}</strong><p>${day(r.date)} · ${e(r.type)} · ${e(events.find(v=>v.id===r.event)?.data.title||'')}</p></div>${badge(r.date<today()&&r.type==='Tarefa'?'Atrasada':r.status)}</a>`).join('')||empty('Sua agenda está livre','Eventos datados e tarefas com prazo aparecem aqui.')}</div>`;
}
function bind(){
 document.querySelector('[data-import-guests]')?.addEventListener('click',importGuests);
 document.querySelector('[data-upload-media]')?.addEventListener('click',mediaUpload);
 document.querySelectorAll('[data-media-toggle]').forEach(b=>b.onclick=async()=>{try{const r=refs.media.find(r=>r.id===b.dataset.mediaToggle);await api('media',{method:'POST',body:{id:r.id,published:!r.published,alt:r.alt}});toast('Publicação atualizada.');render();}catch(err){toast(err.message,true);}});
 document.querySelectorAll('[data-media-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/api/app?action=media&id='+b.dataset.mediaCopy);toast('URL copiada. Cole no campo de imagem do conteúdo.');}catch(err){toast('Não foi possível copiar automaticamente.',true);}});

 document.querySelectorAll('[data-share-access]').forEach(b=>b.onclick=()=>{const grant=refs.grants.find(r=>r.id===b.dataset.shareAccess);const link=location.origin+(grant.role==='client'?'/portal':'/admin');const message='Olá! Seu acesso ao espaço Elass foi autorizado. Acesse '+link+', escolha Primeiro acesso e cadastre o e-mail '+grant.email+'. Crie sua senha com pelo menos 8 caracteres e confirme o código enviado ao e-mail. Depois, entre para acompanhar o planejamento. Estamos à disposição!';modal('Compartilhar acesso',`<div class="dialog-body"><p>Envie esta mensagem à pessoa autorizada. Nenhuma mensagem é enviada automaticamente.</p><label class="field" style="margin-top:16px">Mensagem<textarea id="access-message" rows="7" readonly>${e(message)}</textarea></label><button id="copy-access">Copiar mensagem</button></div>`);document.querySelector('#copy-access').onclick=async()=>{try{await navigator.clipboard.writeText(message);toast('Mensagem copiada.');}catch{document.querySelector('#access-message').select();toast('Selecione e copie a mensagem.');}};});
 document.querySelectorAll('[data-search-result]').forEach(a=>a.onclick=ev=>{ev.preventDefault();eventId=a.dataset.resultEvent||eventId;kind=a.dataset.resultKind==='events'?'event:'+a.dataset.searchResult:a.dataset.resultKind;q=a.dataset.resultTitle;status='';offset=0;history.replaceState({},'','#'+kind);shell();render();});
 document.querySelector('#sort-filter')?.addEventListener('change',ev=>{sortOrder=ev.target.value;offset=0;render();});
 document.querySelector('#period-filter')?.addEventListener('change',ev=>{taskPeriod=ev.target.value;offset=0;render();});

 document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>editRecord(b.dataset.new));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editRecord(kind,rows.find(r=>r.id===b.dataset.edit)));document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{const r=rows.find(r=>r.id===b.dataset.read);modal(r.data.title,`<div class="dialog-body">${definitions[kind].fields.filter(f=>r.data[f.key]&&!['notes','shared'].includes(f.key)).map(f=>`<div style="margin-bottom:18px"><small class="muted">${e(f.label)}</small><p class="description">${e(f.type==='money'?money(r.data[f.key]):r.data[f.key])}</p></div>`).join('')}</div>`);});
 document.querySelector('[data-edit-event]')?.addEventListener('click',ev=>editRecord('events',events.find(r=>r.id===ev.currentTarget.dataset.editEvent)));
 document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>{const r=rows.find(x=>x.id===b.dataset.archive);modal('Arquivar registro?',`<div class="dialog-body"><p>Arquivar ${e(r.data.title)}? O registro sairá das listas ativas e o histórico será preservado.</p></div><div class="dialog-foot"><button data-cancel>Cancelar</button><button class="primary" id="confirm-archive">Arquivar</button></div>`);document.querySelector('#confirm-archive').onclick=async()=>{try{await api('records',{method:'DELETE',body:{kind,id:r.id,version:r.version}});document.querySelector('#modal').close();toast('Registro arquivado.');if(kind==='events'){events=await all('events');shell();}render();}catch(err){toast(err.message,true);}};});
 const search=()=>{q=document.querySelector('#list-search')?.value||'';status=document.querySelector('#status-filter')?.value||'';offset=0;render();};document.querySelector('[data-search]')?.addEventListener('click',search);document.querySelector('#list-search')?.addEventListener('keydown',ev=>{if(ev.key==='Enter')search();});document.querySelector('#status-filter')?.addEventListener('change',search);
 document.querySelector('[data-prev]')?.addEventListener('click',()=>{offset=Math.max(0,offset-50);render();});document.querySelector('[data-next]')?.addEventListener('click',()=>{offset+=50;render();});document.querySelector('[data-view]')?.addEventListener('click',()=>{view=view==='list'?'kanban':'list';render();});
 document.querySelector('[data-export]')?.addEventListener('click',async ev=>{const b=ev.currentTarget;b.disabled=true;try{let exported=[],page=0,more=true;while(more){const r=await api('records',{params:{kind,event:definitions[kind].event?eventId:undefined,q,status,period:kind==='tasks'?taskPeriod:undefined,sort:sortOrder,offset:page,limit:200}});exported.push(...r.rows);page+=200;more=r.more;}csv(kind+'.csv',exported.map(r=>({id:r.id,event_id:r.event_id,...Object.fromEntries(Object.entries(r.data).map(([key,v])=>[key,definitions[kind].fields.find(f=>f.key===key)?.type==='money'?Number(v)/100:v])),rsvp:r.response,attendees:r.attendees,checked_count:r.checked_count})));toast(exported.length+' registros exportados.');}catch(err){toast(err.message,true);}finally{b.disabled=false;}});
 document.querySelector('[data-export-finance]')?.addEventListener('click',async()=>{try{csv('recebimentos.csv',(await allPayments()).map(p=>({...p,valor_reais:Number(p.amount_cents)/100})));}catch(err){toast(err.message,true);}});
 document.querySelector('[data-payment]')?.addEventListener('click',paymentForm);document.querySelector('[data-upload]')?.addEventListener('click',uploadForm);document.querySelector('[data-grant]')?.addEventListener('click',()=>grantForm());document.querySelectorAll('[data-edit-grant]').forEach(b=>b.onclick=()=>grantForm(refs.grants.find(r=>r.id===b.dataset.editGrant)));
 document.querySelectorAll('[data-invite]').forEach(b=>b.onclick=async()=>{try{const r=await api('invite',{method:'POST',body:{id:b.dataset.invite}});const link=location.origin+r.path;modal('Convite privado',`<div class="dialog-body"><p>Compartilhe este link somente com o grupo convidado. Gerar um novo link invalida o anterior.</p><label class="field" style="margin-top:20px">Link de confirmação<input readonly id="invite-link" value="${e(link)}"></label><div class="actions" style="margin-top:15px"><button id="copy-link">Copiar link</button><a class="button" href="${e(link)}" target="_blank" rel="noopener">Abrir confirmação</a></div></div>`);document.querySelector('#copy-link').onclick=async()=>{await navigator.clipboard.writeText(link);toast('Link copiado.');};}catch(err){toast(err.message,true);}});
 document.querySelectorAll('[data-convert]').forEach(b=>b.onclick=async()=>{try{await api('convert',{method:'POST',body:{id:b.dataset.convert}});toast('Contato convertido em cliente. Cadastre o evento em seguida.');render();}catch(err){toast(err.message,true);}});
 document.querySelector('[data-template]')?.addEventListener('click',()=>{if(!eventId){toast('Selecione um evento no topo.',true);return;}modal('Aplicar modelo de checklist',`<form id="template-form"><div class="dialog-body"><label class="field">Modelo<select name="template">${Object.keys(templates).map(k=>`<option>${e(k)}</option>`).join('')}</select></label><p class="muted" style="margin-top:15px">Os prazos são calculados a partir da data do evento. Cada aplicação adiciona novas tarefas.</p></div><div class="dialog-foot"><button data-cancel type="button">Cancelar</button><button class="primary">Adicionar tarefas</button></div></form>`);document.querySelector('#template-form').onsubmit=async ev=>{ev.preventDefault();try{const r=await api('template',{method:'POST',body:{event_id:eventId,template:ev.target.template.value}});document.querySelector('#modal').close();toast(r.count+' tarefas adicionadas.');render();}catch(err){toast(err.message,true);}};});
 document.querySelectorAll('[data-read-notification]').forEach(b=>b.onclick=async()=>{try{await api('notifications',{method:'POST',body:{id:b.dataset.readNotification}});render();}catch(err){toast(err.message,true);}});
 document.querySelector('#check-search')?.addEventListener('input',ev=>document.querySelectorAll('.check-card').forEach(c=>c.hidden=!c.dataset.name.includes(ev.target.value.toLowerCase())));
 document.querySelectorAll('[data-checkin]').forEach(b=>b.onclick=()=>{const r=rows.find(r=>r.id===b.dataset.checkin);modal('Registrar chegada',`<form id="checkin-form"><div class="dialog-body"><h3>${e(r.data.title)}</h3><label class="field" style="margin-top:15px">Pessoas presentes<input type="number" name="count" min="1" max="${r.attendees}" value="${r.attendees}" required></label><p class="muted" style="margin-top:15px">Este registro encerra o check-in do convite. Confirme a quantidade total de presentes do grupo.</p></div><div class="dialog-foot"><button type="button" data-cancel>Cancelar</button><button class="primary">Confirmar chegada</button></div></form>`);document.querySelector('#checkin-form').onsubmit=async ev=>{ev.preventDefault();try{await api('checkin',{method:'POST',body:{event_id:eventId,id:r.id,count:Number(ev.target.count.value)}});document.querySelector('#modal').close();toast('Chegada registrada.');render();}catch(err){toast(err.message,true);}};});
 document.querySelectorAll('[data-download]').forEach(b=>b.onclick=async()=>{try{const a=await getAuth(),token=await a.token();const r=await fetch('/api/app?'+new URLSearchParams({action:'documents',event:eventId,id:b.dataset.download}),{headers:{Authorization:'Bearer '+token.data.token}});if(!r.ok)throw Error('Não foi possível baixar.');download(refs.documents.find(d=>d.id===b.dataset.download).filename,await r.blob());}catch(err){toast(err.message,true);}});
 const bf=document.querySelector('#briefing-form');if(bf){const progress=()=>{const values=[...new FormData(bf).values()],done=values.filter(v=>String(v).trim()).length,total=values.length;document.querySelector('#briefing-progress').textContent=`${done} de ${total} campos preenchidos · complete o que já souber`;document.querySelector('#progress-fill').style.width=100*done/total+'%';};bf.oninput=progress;progress();document.querySelectorAll('[data-save-briefing]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await api('briefing',{method:'POST',body:{event_id:eventId,data:Object.fromEntries(new FormData(bf)),version:refs.briefing.version,complete:b.dataset.saveBriefing==='true'}});refs.briefing=r;document.querySelector('#briefing-saved').textContent='Salvo em '+new Date().toLocaleString('pt-BR');toast(r.complete?'Briefing concluído e enviado à equipe.':'Rascunho salvo.');}catch(err){toast(err.message,true);}finally{b.disabled=false;}});}
}
async function rsvp(){
 const token=new URLSearchParams(location.search).get('token')||location.pathname.split('/')[2];
 try{const r=await api('rsvp',{publicCall:true,params:{token}});app.innerHTML=`<main class="rsvp-page"><a href="/"><img src="/assets/img/logo-bronze.png" alt="Elass Cerimonial"></a><span class="eyebrow">Uma celebração especial</span><h1>${e(r.event)}</h1><p>${day(r.date)}${r.time?' · '+e(r.time):''}</p><p class="muted">${e(r.venue)}<br>${e(r.address)}</p><div class="divider"></div><h2 style="margin:28px 0 8px">${e(r.title)}, contamos com você?</h2><p class="muted">Este convite é válido para até ${r.capacity} pessoa(s).</p><form id="rsvp-form"><label class="field">Confirmação<select name="response"><option ${r.response==='Confirmado'?'selected':''}>Confirmado</option><option ${r.response==='Recusado'?'selected':''}>Recusado</option></select></label><label class="field" style="margin-top:16px">Pessoas que comparecerão<input type="number" name="attendees" min="1" max="${r.capacity}" value="${r.attendees||1}" required></label><button class="primary" style="width:100%;margin-top:22px">Enviar confirmação</button><p id="rsvp-message" role="status" class="muted" style="margin-top:18px;text-align:center">${r.response!=='Aguardando'?'Última resposta: '+e(r.response):'Sua resposta será registrada diretamente com o cerimonial.'}</p></form><p style="font-size:11px;margin-top:30px" class="muted">Precisa de ajuda? <a href="https://wa.me/5531996472045">Fale com a Elass</a> · <a href="/privacidade">Privacidade</a></p></main>`;
 const f=document.querySelector('#rsvp-form');const update=()=>{f.attendees.disabled=f.response.value==='Recusado';};f.response.onchange=update;update();f.onsubmit=async ev=>{ev.preventDefault();const b=f.querySelector('button');b.disabled=true;try{await api('rsvp',{publicCall:true,method:'POST',body:{token,response:f.response.value,attendees:f.response.value==='Recusado'?0:Number(f.attendees.value)}});document.querySelector('#rsvp-message').textContent='Resposta registrada. Obrigado pelo carinho!';toast('Confirmação recebida.');}catch(err){toast(err.message,true);}finally{b.disabled=false;}};
 }catch(err){app.innerHTML=`<main class="rsvp-page"><h2>Não foi possível abrir o convite</h2><p style="margin:20px 0">${e(err.message)}</p><a href="https://wa.me/5531996472045" class="button">Falar com o cerimonial</a></main>`;}
}
async function start(){if(location.pathname.startsWith('/rsvp'))return rsvp();const params=new URLSearchParams(location.search);if(params.get('token')&&params.get('reset'))return authScreen('','reset');
 try{user=await api('me');events=await all('events');eventId=sessionStorage.getItem('elass-event')||'';if(!events.some(r=>r.id===eventId))eventId=manager()?'':events[0]?.id||'';kind=location.hash.slice(1)||({'crm':'leads','eventos':'events','clientes':'clients','financeiro':'payments','fornecedores':'suppliers','tarefas':'tasks','contratos':'contracts','convidados':'guests','equipe':'grants','site':'site','configuracoes':'grants'}[location.pathname.split('/')[2]])||(location.pathname==='/checkin'?'checkin':'')||(!manager()?(user.role==='checkin'?'checkin':'portal'):'dashboard');shell();await render();}catch(err){await authScreen(err.message.includes('Entre na sua conta')?'':err.message);}}
window.addEventListener('hashchange',()=>{if(!user)return;const next=location.hash.slice(1)||'dashboard';if(kind!==next){if(next!=='search')q='';status='';taskPeriod='';offset=0;}kind=next;document.querySelector('.sidebar')?.classList.remove('open');render();window.scrollTo(0,0);});
start();
